<script setup lang="ts">
import { onMounted, reactive, ref } from "vue"
import { useRoute, useRouter } from "vue-router"
import { ElMessage } from "element-plus"
import { bidApi } from "../../api/bid"
import { HttpError } from "../../shared/http"
import { useAuthStore } from "../../stores/auth"
import { ITEM_STATUS_LABELS, NO_QUOTE_REASON_LABELS, PROJECT_STATUS_LABELS, type BidCandidate, type BidItemStatus, type BidProjectDetail, type BidProjectItem, type NoQuoteReason } from "../../types/bid"
const route=useRoute();const router=useRouter();const auth=useAuthStore();const id=String(route.params.id);const project=ref<BidProjectDetail>();const rows=ref<BidProjectItem[]>([]);const total=ref(0);const page=ref(1);const pageSize=ref(50);const loading=ref(false);const filters=reactive({keyword:"",status:undefined as BidItemStatus|undefined});const drawer=ref(false);const candidates=ref<BidCandidate[]>([]);const candidateLoading=ref(false);const item=ref<BidProjectItem>();const priceVisible=ref(false);const candidate=ref<BidCandidate>();const price=ref("");const note=ref("");const noQuoteVisible=ref(false);const noQuote=reactive({reason:"NO_PRODUCT_MATCH" as NoQuoteReason,reason_detail:""});
const terminal=()=>["WON","LOST","VOIDED"].includes(project.value?.status??"");const canSelect=(row:BidProjectItem)=>auth.hasPermission("bid:select")&&!terminal()&&["SELECTING","READY","EXPORTED"].includes(project.value?.status??"")&&!["PENDING"].includes(row.status)
async function load(){loading.value=true;try{const [detail,result]=await Promise.all([bidApi.get(id),bidApi.items(id,{page:page.value,page_size:pageSize.value,status:filters.status,keyword:filters.keyword.trim()||undefined})]);project.value=detail;rows.value=result.items;total.value=result.total;page.value=result.page}catch(e){ElMessage.error(e instanceof HttpError?e.response.message:"加载工作台失败")}finally{loading.value=false}}
async function openCandidates(row:BidProjectItem){item.value=row;drawer.value=true;candidateLoading.value=true;try{candidates.value=await bidApi.candidates(id,row.id)}catch(e){ElMessage.error(e instanceof HttpError?e.response.message:"加载候选失败")}finally{candidateLoading.value=false}}
function pick(value:BidCandidate){candidate.value=value;price.value="";note.value="";priceVisible.value=true}
async function select(){if(!item.value||!candidate.value||!/^\d+(\.\d+)?$/.test(price.value)||Number(price.value)<=0)return ElMessage.error("请输入大于 0 的选品单价");if(item.value.max_price&&Number(price.value)>Number(item.value.max_price))return ElMessage.error("选品单价不能高于需求限价");try{await bidApi.select(id,item.value.id,{candidate_id:candidate.value.candidate_id,selected_unit_price:price.value,note:note.value});priceVisible.value=false;drawer.value=false;ElMessage.success("选品已保存");await load()}catch(e){ElMessage.error(e instanceof HttpError?e.response.message:"选品失败")}}
function openNoQuote(row:BidProjectItem){item.value=row;noQuote.reason="NO_PRODUCT_MATCH";noQuote.reason_detail="";noQuoteVisible.value=true}
async function markNoQuote(){if(!item.value)return;if(noQuote.reason==="OTHER"&&!noQuote.reason_detail.trim())return ElMessage.error("其他原因必须填写说明");try{await bidApi.noQuote(id,item.value.id,noQuote);noQuoteVisible.value=false;ElMessage.success("已标记无法报价");await load()}catch(e){ElMessage.error(e instanceof HttpError?e.response.message:"操作失败")}}
function snapshot(selection:any,key:string){return selection?.[key]??{}};onMounted(()=>void load())
</script>
<template><div class="workbench" v-loading="loading"><header><el-button @click="router.push(`/bid-projects/${id}`)">返回项目详情</el-button><span v-if="project">{{project.project_code}} / {{project.project_name}} / {{PROJECT_STATUS_LABELS[project.status]}}</span></header><el-alert v-if="terminal()" title="项目已结束，工作台仅供只读查看。" type="info" :closable="false"/><el-form inline><el-input v-model="filters.keyword" clearable placeholder="搜索需求名称、品牌、型号或客户编码" @change="page=1;load()"/><el-select v-model="filters.status" clearable placeholder="全部状态" @change="page=1;load()"><el-option v-for="(label,key) in ITEM_STATUS_LABELS" :key="key" :label="label" :value="key"/></el-select><el-button type="primary" @click="page=1;load()">查询</el-button></el-form><el-table :data="rows" max-height="620"><el-table-column prop="source_row_number" label="Excel 行号" width="95"/><el-table-column prop="buyer_item_code" label="客户商品编码" min-width="130"/><el-table-column prop="product_name" label="商品名称" min-width="150"/><el-table-column prop="brand" label="品牌"/><el-table-column prop="model" label="型号" min-width="120"/><el-table-column prop="specification" label="规格" min-width="150"/><el-table-column prop="quantity" label="数量"/><el-table-column prop="unit" label="单位"/><el-table-column prop="max_price" label="最高限价"/><el-table-column label="匹配状态"><template #default="{row}"><el-tag>{{ITEM_STATUS_LABELS[row.status]}}</el-tag></template></el-table-column><el-table-column label="当前选中商品" min-width="180"><template #default="{row}"><template v-if="row.current_selection"><div>{{snapshot(row.current_selection,'product_snapshot').product_name}} {{snapshot(row.current_selection,'product_snapshot').brand}} {{snapshot(row.current_selection,'product_snapshot').model}}</div><small>SKU: {{snapshot(row.current_selection,'product_snapshot').sku??'—'}}</small></template><span v-else>—</span></template></el-table-column><el-table-column label="当前供应商" min-width="160"><template #default="{row}"><template v-if="row.current_selection">{{snapshot(row.current_selection,'supplier_snapshot').supplier_name}} / {{snapshot(row.current_selection,'supplier_snapshot').supplier_code}}</template><span v-else>—</span></template></el-table-column><el-table-column label="当前选中单价"><template #default="{row}">{{row.current_selection?.selected_unit_price??'—'}}</template></el-table-column><el-table-column label="操作" fixed="right" width="150"><template #default="{row}"><el-button v-if="canSelect(row)&&['NO_MATCH','UNIQUE_MATCH','MULTIPLE_MATCH','SELECTED'].includes(row.status)" link type="primary" @click="openCandidates(row)">{{row.status==='SELECTED'?'重新选择':'选择商品'}}</el-button><el-button v-if="canSelect(row)" link type="warning" @click="openNoQuote(row)">无法报价</el-button></template></el-table-column></el-table><el-pagination v-model:current-page="page" v-model:page-size="pageSize" :page-sizes="[20,50,100]" layout="total, sizes, prev, pager, next" :total="total" @current-change="load" @size-change="()=>{page=1;load()}"/><el-drawer v-model="drawer" title="候选商品" size="min(760px,95vw)"><el-table v-loading="candidateLoading" :data="candidates"><el-table-column prop="rank" label="排名"/><el-table-column prop="score" label="评分"/><el-table-column prop="product_name" label="商品" min-width="160"/><el-table-column label="供应商" min-width="160"><template #default="{row}">{{row.supplier_code}} / {{row.supplier_name}}</template></el-table-column><el-table-column prop="cost_price" label="成本价"/><el-table-column prop="agreement_price" label="协议价"/><el-table-column prop="jd_price" label="京东价"/><el-table-column label="匹配信息" min-width="200"><template #default="{row}"><div>方式：{{row.method}}</div><div>规则版本：{{row.match_reason.rules_version??'—'}}</div><el-collapse><el-collapse-item title="更多匹配信息">品牌：{{row.match_reason.brand_match??'—'}}；型号：{{row.match_reason.model_match??'—'}}；名称：{{row.match_reason.name_match??'—'}}；规格：{{row.match_reason.specification_match??'—'}}；类目：{{row.match_reason.category_match??'—'}}</el-collapse-item></el-collapse></template></el-table-column><el-table-column v-if="auth.hasPermission('bid:select')&&!terminal()" label="操作"><template #default="{row}"><el-button link type="primary" @click="pick(row)">选择</el-button></template></el-table-column></el-table></el-drawer><el-dialog v-model="priceVisible" title="确认选品价格"><div v-if="candidate">成本价：{{candidate.cost_price}}；协议价：{{candidate.agreement_price??'—'}}；京东价：{{candidate.jd_price??'—'}}；最高限价：{{item?.max_price??'—'}}</div><el-input v-model="price" placeholder="最终选品单价（必填）"/><el-input v-model="note" type="textarea" placeholder="备注（可选）"/><template #footer><el-button @click="priceVisible=false">取消</el-button><el-button type="primary" @click="select">确认选品</el-button></template></el-dialog><el-dialog v-model="noQuoteVisible" title="无法报价"><el-select v-model="noQuote.reason"><el-option v-for="(label,key) in NO_QUOTE_REASON_LABELS" :key="key" :label="label" :value="key"/></el-select><el-input v-if="noQuote.reason==='OTHER'" v-model="noQuote.reason_detail" type="textarea" placeholder="请填写其他原因"/><template #footer><el-button @click="noQuoteVisible=false">取消</el-button><el-button type="warning" @click="markNoQuote">确认</el-button></template></el-dialog></div></template><style scoped>.workbench{display:grid;gap:16px}.workbench header{display:flex;align-items:center;gap:14px}.el-pagination{justify-content:end}.el-input{margin:8px 0}</style>
